const renewAgentRunControlFanoutTargetLease = `-- name: RenewAgentRunControlFanoutTargetLease :one
WITH locked_target AS MATERIALIZED (
    SELECT targets.tenant_id, targets.fanout_id, targets.agent_run_id,
           targets.claim_expires_at, targets.updated_at
    FROM agent.agent_run_control_fanout_targets AS targets
    WHERE targets.tenant_id = $2
      AND targets.fanout_id = $3
      AND targets.agent_run_id = $4
      AND targets.claim_worker_id = $5
      AND targets.claim_fencing_token = $6
    FOR UPDATE OF targets
),
operation_time AS MATERIALIZED (
    SELECT clock_timestamp() AS occurred_at FROM locked_target
),
renewal_time AS MATERIALIZED (
    SELECT GREATEST(
        operation_time.occurred_at,
        locked_target.updated_at + interval '1 microsecond'
    ) AS occurred_at
    FROM locked_target
    CROSS JOIN operation_time
)
UPDATE agent.agent_run_control_fanout_targets AS targets
SET claim_expires_at = GREATEST(
        locked_target.claim_expires_at,
        renewal_time.occurred_at + $1::interval
    ),
    updated_at = renewal_time.occurred_at
FROM locked_target
CROSS JOIN operation_time
CROSS JOIN renewal_time
WHERE targets.tenant_id = locked_target.tenant_id
  AND targets.fanout_id = locked_target.fanout_id
  AND targets.agent_run_id = locked_target.agent_run_id
  AND locked_target.claim_expires_at > operation_time.occurred_at
RETURNING targets.tenant_id, targets.work_order_id, targets.fanout_id, targets.authority_kind, targets.agent_run_id, targets.runtime_run_id, targets.target_fencing_token, targets.system_safety_control_id, targets.system_safety_control_digest, targets.command_id, targets.control_state, targets.claim_fencing_token, targets.claim_worker_id, targets.claim_expires_at, targets.updated_at
`

type RenewAgentRunControlFanoutTargetLeaseParams struct {
	LeaseDuration     pgtype.Interval
	TenantID          string
	FanoutID          string
	AgentRunID        string
	WorkerID          *string
	ClaimFencingToken int64
}

func (q *Queries) RenewAgentRunControlFanoutTargetLease(ctx context.Context, arg RenewAgentRunControlFanoutTargetLeaseParams) (AgentRunControlFanoutTarget, error) {
	row := q.db.QueryRow(ctx, renewAgentRunControlFanoutTargetLease,
		arg.LeaseDuration,
		arg.TenantID,
		arg.FanoutID,
		arg.AgentRunID,
		arg.WorkerID,
		arg.ClaimFencingToken,
	)
	var i AgentRunControlFanoutTarget
	err := row.Scan(
		&i.TenantID,
		&i.WorkOrderID,
		&i.FanoutID,
		&i.AuthorityKind,
		&i.AgentRunID,
		&i.RuntimeRunID,
		&i.TargetFencingToken,
		&i.SystemSafetyControlID,
		&i.SystemSafetyControlDigest,
		&i.CommandID,
		&i.ControlState,
		&i.ClaimFencingToken,
		&i.ClaimWorkerID,
		&i.ClaimExpiresAt,
		&i.UpdatedAt,
	)
	return i, err
}
